//! Executable toy only: no Raft algorithm, invariant or solution is supplied.
#[path = "support.rs"]
mod support;
use support::*;
use vstd::prelude::*;
verus! {
pub open spec fn message(recipient: nat, body: u64) -> Envelope<u64> {
    Envelope { group: 1, sender: 0, recipient, body }
}
pub open spec fn emitted(o: (u64, u64)) -> Seq<Envelope<u64>> {
    seq![message(1, o.0), message(2, o.1)]
}
pub open spec fn receive(i: Option<Delivery<u64>>) -> Option<Delivery<u64>> { i }
pub open spec fn payload(i: Option<Delivery<u64>>) -> Option<u64> {
    match i { Some(d) => Some(d.message.body), None => None }
}
pub open spec fn initial(s: u64) -> bool { s == 0 }
pub open spec fn step(s: u64, i: Option<Delivery<u64>>, t: u64, o: (u64, u64)) -> bool {
    t == (if s < 100 { s + 1 } else { s as int }) && o == (match payload(i) { Some(v) => v, None => 7u64 }, 9u64)
}
pub open spec fn model_initial(s: nat) -> bool { s == 0 }
pub open spec fn model_step(s: nat, i: Option<Delivery<u64>>, t: nat, o: (u64, u64)) -> bool {
    t == (if s < 100 { s + 1 } else { s }) && o == (match payload(i) { Some(v) => v, None => 7u64 }, 9u64)
}
pub open spec fn view(s: u64) -> nat { s as nat }
pub open spec fn bounded(s: u64, sent: Seq<Envelope<u64>>) -> bool { s <= 100 }

pub fn new_counter() -> (s: u64) ensures initial(s) { 0 }

// Deliberately disagrees with a possible application expectation that both
// recipients receive the same value. Authenticity must not conceal this bug.
pub fn handle(s: u64, input: Option<u64>) -> (r: (u64, (u64, u64)))
    ensures forall|i: Option<Delivery<u64>>| #[trigger] payload(i) == input ==> step(s, i, r.0, r.1),
{
    let t = if s < 100 { s + 1 } else { s };
    let first = match input { Some(value) => value, None => 7 };
    (t, (first, 9))
}

pub proof fn network_examples() {
    let a = message(1, 7);
    let b = message(2, 9);
    let empty = Seq::<Envelope<u64>>::empty();
    assert(!delivered(empty, Delivery { send: 0, message: a }));
    let sent = emitted((7, 9));
    assert(exchange(empty, None, sent, sent));
    assert(exchange(sent, Some(Delivery { send: 1, message: b }), empty, sent));
    // Delay the first message; deliver the second again, without consuming it.
    assert(exchange(sent, Some(Delivery { send: 1, message: b }), empty, sent));
    assert(exchange(sent, Some(Delivery { send: 0, message: a }), empty, sent));
    // A crash/no-delivery step does not erase provenance; loss is non-delivery.
    assert(exchange(sent, None, empty, sent));
    assert(!delivered(sent, Delivery { send: 0, message: message(1, 9) }));
    assert(!delivered(sent, Delivery { send: 0, message: message(2, 7) }));
    assert(!delivered(sent, Delivery { send: 0, message: Envelope { group: 2, ..a } }));
    assert(!delivered(sent, Delivery { send: 0, message: Envelope { sender: 2, ..a } }));
    let h = History { states: seq![(), (), (), (), (), ()],
        inputs: seq![None, Some(Delivery { send: 1, message: b }),
            Some(Delivery { send: 1, message: b }), Some(Delivery { send: 0, message: a }), None],
        outputs: seq![sent, empty, empty, empty, empty],
        sent: seq![empty, sent, sent, sent, sent, sent] };
    assert forall|k: int| 0 <= k < h.inputs.len() implies
        exchange(h.sent[k], #[trigger] h.inputs[k], h.outputs[k], h.sent[k+1]) by {
        assert(k == 0 || k == 1 || k == 2 || k == 3 || k == 4);
    }
    assert(valid(h, |s: ()| true, |s: (), i: Option<Delivery<u64>>, t: (), o: Seq<Envelope<u64>>| true,
        |i| i, |o| o));
}

pub fn actual_bug_is_admitted() {
    let (s, o) = handle(new_counter(), None);
    proof {
        assert(payload(None) == None::<u64>);
        assert(step(0, None, s, o));
        let sent = emitted(o);
        assert(o.0 != o.1);
        assert(delivered(sent, Delivery { send: 0, message: message(1, o.0) }));
        assert(delivered(sent, Delivery { send: 1, message: message(2, o.1) }));
    }
}

pub proof fn complete_toy_history(h: History<u64, Option<Delivery<u64>>, (u64, u64), u64>, k: int)
    requires valid(h, |s| initial(s), |s, i, t, o| step(s, i, t, o), |i| receive(i), |o| emitted(o)), 0 <= k < h.states.len(),
    ensures bounded(h.states[k], h.sent[k]),
        valid(project(h, |s| view(s)), |s| model_initial(s), |s, i, t, o| model_step(s, i, t, o), |i| receive(i), |o| emitted(o)),
{
    assert forall|s: u64| initial(s) implies #[trigger] bounded(s, Seq::empty()) && model_initial(view(s)) by {}
    assert forall|s: u64, i: Option<Delivery<u64>>, t: u64, o: (u64, u64), a: Seq<Envelope<u64>>, b: Seq<Envelope<u64>>|
        #[trigger] bounded(s, a) && #[trigger] step(s, i, t, o) && #[trigger] exchange(a, receive(i), emitted(o), b)
        implies bounded(t, b) && model_step(view(s), i, view(t), o) by {}
    invariant_at(h, |s| initial(s), |s, i, t, o| step(s, i, t, o), |i| receive(i), |o| emitted(o), |s, sent| bounded(s, sent), k);
    simulate(h, |s| initial(s), |s, i, t, o| step(s, i, t, o), |s| model_initial(s), |s, i, t, o| model_step(s, i, t, o), |i| receive(i), |o| emitted(o), |s| view(s), |s, sent| bounded(s, sent));
}
} // verus!
//! Independent callers, DRAFT. Candidate types are proof adapters, not a runtime architecture.
#[path = "targets.rs"]
mod targets;
#[path = "support.rs"]
mod support;
#[path = "../madraft/proof/implementation.rs"]
mod implementation;
use vstd::prelude::*;
use implementation as c;

verus! {
pub type Execution = support::History<c::State, c::Input, c::Output, c::Message>;
pub open spec fn execution(h: Execution) -> bool {
    support::valid(h, |s| c::initial(s), |s,i,t,o| c::step(s,i,t,o), |i| c::receive(i), |o| c::emit(o))
}
// runtime interface begin
pub type RuntimeExecution = support::History<c::RuntimeState, c::Input, c::Output, c::Message>;
pub open spec fn runtime_execution(h: RuntimeExecution) -> bool {
    support::valid(h, |s| c::runtime_initial(s), |s,i,t,o| c::runtime_step(s,i,t,o), |i| c::receive(i), |o| c::emit(o))
}
pub open spec fn abstract_execution(h: RuntimeExecution) -> Execution {
    support::project(h, |s| c::view(s))
}
// runtime interface end
// obligation: election_safety
pub proof fn election_safety(run: Execution)
    requires execution(run),
    ensures targets::election_safety(c::observe(run)),
{ c::prove_election_safety(run); }

// obligation: leader_append_only
pub proof fn leader_append_only(run: Execution)
    requires execution(run),
    ensures targets::leader_append_only(c::observe(run)),
{ c::prove_leader_append_only(run); }

// obligation: log_matching
pub proof fn log_matching(run: Execution)
    requires execution(run),
    ensures targets::log_matching(c::observe(run)),
{ c::prove_log_matching(run); }

// obligation: leader_completeness
pub proof fn leader_completeness(run: Execution)
    requires execution(run),
    ensures targets::leader_completeness(c::observe(run)),
{ c::prove_leader_completeness(run); }

// obligation: state_machine_safety
pub proof fn state_machine_safety(run: Execution)
    requires execution(run),
    ensures targets::state_machine_safety(c::observe(run)),
{ c::prove_state_machine_safety(run); }

// obligation: execution_link
pub proof fn execution_link(run: RuntimeExecution)
    requires runtime_execution(run),
    ensures execution(abstract_execution(run)),
        abstract_execution(run).inputs == run.inputs,
        abstract_execution(run).outputs == run.outputs,
        abstract_execution(run).sent == run.sent,
{
    assert forall|s: c::RuntimeState| c::runtime_initial(s) implies
        #[trigger] c::runtime_invariant(s, Seq::empty()) && c::initial(c::view(s)) by {
        c::prove_runtime_initial(s);
    }
    assert forall|s: c::RuntimeState, i: c::Input, t: c::RuntimeState, o: c::Output,
        a: Seq<support::Envelope<c::Message>>, b: Seq<support::Envelope<c::Message>>|
        #[trigger] c::runtime_invariant(s,a) && #[trigger] c::runtime_step(s,i,t,o)
        && #[trigger] support::exchange(a,c::receive(i),c::emit(o),b)
        implies c::runtime_invariant(t,b) && c::step(c::view(s),i,c::view(t),o) by {
        c::prove_runtime_step(s,i,t,o,a,b);
    }
    support::simulate(run, |s| c::runtime_initial(s), |s,i,t,o| c::runtime_step(s,i,t,o),
        |s| c::initial(s), |s,i,t,o| c::step(s,i,t,o), |i| c::receive(i), |o| c::emit(o),
        |s| c::view(s), |s,sent| c::runtime_invariant(s,sent));
}

// obligation: snapshot_observation
pub proof fn snapshot_and_observation_shape(run: Execution)
    requires execution(run),
    ensures targets::shape(c::observe(run)),
        targets::snapshot_fidelity(c::observe(run), c::applications()),
{ c::prove_observation_and_snapshots(run); }

// obligation: nonempty_execution
// Necessary witness from executable-side initialization/steps, not coverage by itself.
pub proof fn nonempty_execution()
    ensures exists|run: RuntimeExecution| runtime_execution(run)
        && targets::shape(c::observe(abstract_execution(run)))
        && exists|i: int| 0 <= i < c::observe(abstract_execution(run)).events.len()
            && !(c::observe(abstract_execution(run)).events[i] is Silent),
{
    let run = c::execution_witness();
    assert(runtime_execution(run));
    assert(targets::shape(c::observe(abstract_execution(run))));
    assert(exists|i: int| 0 <= i < c::observe(abstract_execution(run)).events.len()
        && !(c::observe(abstract_execution(run)).events[i] is Silent));
}

// obligation: composed_safety
pub proof fn actual_execution_safety(run: RuntimeExecution)
    requires runtime_execution(run),
    ensures targets::election_safety(c::observe(abstract_execution(run))),
        targets::leader_append_only(c::observe(abstract_execution(run))),
        targets::log_matching(c::observe(abstract_execution(run))),
        targets::leader_completeness(c::observe(abstract_execution(run))),
        targets::state_machine_safety(c::observe(abstract_execution(run))),
        targets::shape(c::observe(abstract_execution(run))),
        targets::snapshot_fidelity(c::observe(abstract_execution(run)), c::applications()),
{
    execution_link(run);
    let h = abstract_execution(run);
    election_safety(h); leader_append_only(h); log_matching(h);
    leader_completeness(h); state_machine_safety(h);
    snapshot_and_observation_shape(h);
}
} // verus!

//! Protocol-independent finite histories. Ghost send indices are not wire fields.
use vstd::prelude::*;
verus! {
pub struct Envelope<M> { pub group: nat, pub sender: nat, pub recipient: nat, pub body: M }
pub struct Delivery<M> { pub send: nat, pub message: Envelope<M> }

pub open spec fn delivered<M>(sent: Seq<Envelope<M>>, d: Delivery<M>) -> bool {
    d.send < sent.len() && sent[d.send as int] == d.message
}

pub open spec fn exchange<M>(sent: Seq<Envelope<M>>, input: Option<Delivery<M>>,
    output: Seq<Envelope<M>>, next: Seq<Envelope<M>>) -> bool {
    (match input { Some(d) => delivered(sent, d), None => true }) && next == sent + output
}

// Adapter types, not a required executable architecture. A step may be a host
// operation, constructor, handler segment or other justified linearization.
pub struct History<S, I, O, M> {
    pub states: Seq<S>, pub inputs: Seq<I>, pub outputs: Seq<O>,
    pub sent: Seq<Seq<Envelope<M>>>,
}

pub open spec fn valid<S, I, O, M>(h: History<S, I, O, M>, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>) -> bool {
    &&& h.states.len() == h.inputs.len() + 1
    &&& h.outputs.len() == h.inputs.len()
    &&& h.sent.len() == h.states.len()
    &&& h.sent[0] == Seq::<Envelope<M>>::empty()
    &&& initial(h.states[0])
    &&& forall|k: int| 0 <= k < h.inputs.len() ==> step(h.states[k], #[trigger] h.inputs[k], h.states[k+1], h.outputs[k])
        && exchange(h.sent[k], receive(h.inputs[k]), emit(h.outputs[k]), h.sent[k+1])
}

pub proof fn invariant_at<S, I, O, M>(h: History<S, I, O, M>, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>, inv: spec_fn(S, Seq<Envelope<M>>) -> bool, k: int)
    requires valid(h, initial, step, receive, emit), 0 <= k < h.states.len(),
        forall|s: S| initial(s) ==> #[trigger] inv(s, Seq::empty()),
        forall|s: S, i: I, t: S, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
            #[trigger] inv(s, a) && #[trigger] step(s, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b) ==> inv(t, b),
    ensures inv(h.states[k], h.sent[k]),
    decreases k,
{
    if k > 0 {
        invariant_at(h, initial, step, receive, emit, inv, k-1);
        assert(h.inputs.len() == h.states.len() - 1);
        assert(step(h.states[k-1], h.inputs[k-1], h.states[k], h.outputs[k-1]));
    }
}

pub open spec fn project<R, S, I, O, M>(h: History<R, I, O, M>, view: spec_fn(R) -> S) -> History<S, I, O, M> {
    History { states: Seq::new(h.states.len(), |k: int| view(h.states[k])),
        inputs: h.inputs, outputs: h.outputs, sent: h.sent }
}

// Coverage direction: every admitted executable history maps to a model history,
// preserving received inputs, actual output messages, and send provenance.
pub proof fn simulate<R, S, I, O, M>(h: History<R, I, O, M>, rinit: spec_fn(R) -> bool,
    rstep: spec_fn(R, I, R, O) -> bool, initial: spec_fn(S) -> bool,
    step: spec_fn(S, I, S, O) -> bool, receive: spec_fn(I) -> Option<Delivery<M>>,
    emit: spec_fn(O) -> Seq<Envelope<M>>, view: spec_fn(R) -> S,
    inv: spec_fn(R, Seq<Envelope<M>>) -> bool)
    requires valid(h, rinit, rstep, receive, emit),
        forall|r: R| rinit(r) ==> #[trigger] inv(r, Seq::empty()) && initial(view(r)),
        forall|r: R, i: I, t: R, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
            #[trigger] inv(r, a) && #[trigger] rstep(r, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b)
                ==> inv(t, b) && step(view(r), i, view(t), o),
    ensures valid(project(h, view), initial, step, receive, emit),
{
    assert forall|r: R| rinit(r) implies #[trigger] inv(r, Seq::empty()) by {}
    assert forall|r: R, i: I, t: R, o: O, a: Seq<Envelope<M>>, b: Seq<Envelope<M>>|
        #[trigger] inv(r, a) && #[trigger] rstep(r, i, t, o) && #[trigger] exchange(a, receive(i), emit(o), b)
            implies inv(t, b) by {}
    invariant_at(h, rinit, rstep, receive, emit, inv, 0);
    assert(initial(view(h.states[0])));
    let p = project(h, view);
    assert forall|k: int| 0 <= k < p.inputs.len() implies step(p.states[k], #[trigger] p.inputs[k], p.states[k+1], p.outputs[k])
        && exchange(p.sent[k], receive(p.inputs[k]), emit(p.outputs[k]), p.sent[k+1]) by {
        invariant_at(h, rinit, rstep, receive, emit, inv, k);
        assert(rstep(h.states[k], h.inputs[k], h.states[k+1], h.outputs[k]));
    }
}
} // verus!
//! DRAFT independent behavioral targets. This is an observation vocabulary,
//! not a prescribed executable representation or a second protocol engine.
use vstd::prelude::*;

verus! {
pub type Group = nat;
pub type Node = nat;
pub type Term = nat;
pub type Index = nat;

pub struct Key { pub group: Group, pub node: Node }
pub struct Entry { pub term: Term, pub command: Seq<u8> }
pub struct Snapshot {
    pub through: Index,
    pub last_term: Term,
    pub bytes: Seq<u8>,
}
pub struct View {
    pub term: Term,
    pub leader: bool,
    // The logical prefix includes compacted entries. It is NOT a free witness:
    // the generated refinement must connect it to actual execution and storage.
    pub log: Seq<Entry>,
    pub snapshot: Option<Snapshot>,
}
pub enum Event {
    Silent,
    Elect { who: Key, term: Term },
    // Observe actual commit-index advancement, never future preservation.
    Commit { who: Key, term: Term, through: Index },
    Apply { who: Key, index: Index, entry: Entry },
    // Logical application of the prefix represented by an installed snapshot.
    ApplySnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    CreateSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    PersistSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
    RestoreSnapshot { who: Key, prefix: Seq<Entry>, snapshot: Snapshot },
}
pub struct History {
    // before/after each linearized action, including crash and restart.
    pub states: Seq<Map<Key, View>>,
    pub events: Seq<Event>,
}

pub open spec fn prefix(a: Seq<Entry>, b: Seq<Entry>) -> bool {
    a.len() <= b.len() && a == b.take(a.len() as int)
}
pub open spec fn at(log: Seq<Entry>, index: Index) -> Entry
    recommends 1 <= index <= log.len(),
{ log[index as int - 1] }

pub open spec fn shape(h: History) -> bool {
    h.states.len() == h.events.len() + 1
    && forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::Elect { who, term } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].leader
            && h.states[t + 1][who].term == term,
        Event::Commit { who, term, through } =>
            h.states[t + 1].contains_key(who)
            && h.states[t + 1][who].term == term
            && 1 <= through <= h.states[t + 1][who].log.len(),
        Event::Apply { who: _, index, entry: _ } => index >= 1,
        _ => true,
    }
}

pub open spec fn election_safety(h: History) -> bool {
    forall |i: int, j: int| #![trigger h.events[i], h.events[j]] 0 <= i < h.events.len() && 0 <= j < h.events.len() ==>
        match (h.events[i], h.events[j]) {
            (Event::Elect { who: a, term: ta }, Event::Elect { who: b, term: tb }) =>
                a.group == b.group && ta == tb ==> a.node == b.node,
            _ => true,
        }
}

pub open spec fn leader_append_only(h: History) -> bool {
    forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.events.len()
        && h.states[t].contains_key(k) && h.states[t + 1].contains_key(k)
        && h.states[t][k].leader && h.states[t + 1][k].leader
        && h.states[t][k].term == h.states[t + 1][k].term
        ==> prefix(h.states[t][k].log, h.states[t + 1][k].log)
}

pub open spec fn log_matching(h: History) -> bool {
    // Compare represented logs across time as well as between nodes.
    forall |s: int, t: int, a: Key, b: Key, index: Index|
        #![trigger at(h.states[s][a].log, index), at(h.states[t][b].log, index)]
        0 <= s < h.states.len() && 0 <= t < h.states.len()
        && a.group == b.group && h.states[s].contains_key(a) && h.states[t].contains_key(b)
        && 1 <= index <= h.states[s][a].log.len() && index <= h.states[t][b].log.len()
        && at(h.states[s][a].log, index).term == at(h.states[t][b].log, index).term
        ==> h.states[s][a].log.take(index as int) == h.states[t][b].log.take(index as int)
}

pub open spec fn leader_completeness(h: History) -> bool {
    forall |c: int, e: int| #![trigger h.events[c], h.events[e]] 0 <= c < h.events.len() && 0 <= e < h.events.len() ==>
        match (h.events[c], h.events[e]) {
            (Event::Commit { who: a, term: tc, through }, Event::Elect { who: b, term: te }) =>
                a.group == b.group && tc < te ==>
                    h.states[e + 1].contains_key(b)
                    && through <= h.states[e + 1][b].log.len()
                    && h.states[c + 1][a].log.take(through as int)
                        == h.states[e + 1][b].log.take(through as int),
            _ => true,
        }
}

pub open spec fn applied(event: Event, group: Group, index: Index) -> Option<Entry> {
    match event {
        Event::Apply { who, index: i, entry } =>
            if who.group == group && i == index { Some(entry) } else { None },
        Event::ApplySnapshot { who, prefix, snapshot: _ } =>
            if who.group == group && 1 <= index <= prefix.len() {
                Some(at(prefix, index))
            } else { None },
        _ => None,
    }
}

pub open spec fn state_machine_safety(h: History) -> bool {
    forall |a: int, b: int, group: Group, index: Index|
        0 <= a < h.events.len() && 0 <= b < h.events.len()
        && applied(h.events[a], group, index).is_some()
        && applied(h.events[b], group, index).is_some()
        ==> applied(h.events[a], group, index) == applied(h.events[b], group, index)
}

// The application semantics is selected per group and refined to the actual
// service. Decoding recovers application state, not historical commands.
pub struct Application {
    pub initial: Seq<u8>,
    pub step: spec_fn(Seq<u8>, Entry) -> Seq<u8>,
    pub decode: spec_fn(Seq<u8>) -> Option<Seq<u8>>,
}
pub open spec fn fold(app: Application, entries: Seq<Entry>) -> Seq<u8>
    decreases entries.len(),
{
    if entries.len() == 0 { app.initial }
    else { (app.step)(fold(app, entries.drop_last()), entries.last()) }
}
pub open spec fn snapshot_represents(app: Application, snap: Snapshot, entries: Seq<Entry>) -> bool {
    snap.through == entries.len()
    && snap.last_term == (if entries.len() == 0 { 0nat } else { entries.last().term })
    && (app.decode)(snap.bytes) == Some(fold(app, entries))
}
pub open spec fn committed_prefix_before(h: History, time: int, group: Group, entries: Seq<Entry>) -> bool {
    entries.len() == 0 || exists |c: int| #![trigger h.events[c]] 0 <= c < time && match h.events[c] {
        Event::Commit { who, term: _, through } => who.group == group
            && entries.len() <= through && h.states[c + 1].contains_key(who)
            && prefix(entries, h.states[c + 1][who].log),
        _ => false,
    }
}
pub open spec fn snapshot_fidelity(h: History, apps: Map<Group, Application>) -> bool {
    (forall |t: int, k: Key| #![trigger h.states[t][k]] 0 <= t < h.states.len() && h.states[t].contains_key(k) ==>
        match h.states[t][k].snapshot {
            None => true,
            Some(s) => apps.contains_key(k.group) && s.through <= h.states[t][k].log.len()
                && snapshot_represents(apps[k.group], s, h.states[t][k].log.take(s.through as int))
                && committed_prefix_before(h, t, k.group, h.states[t][k].log.take(s.through as int)),
        })
    && (forall |t: int| 0 <= t < h.events.len() ==> match #[trigger] h.events[t] {
        Event::ApplySnapshot { who, prefix, snapshot }
        | Event::CreateSnapshot { who, prefix, snapshot }
        | Event::PersistSnapshot { who, prefix, snapshot }
        | Event::RestoreSnapshot { who, prefix, snapshot } =>
            apps.contains_key(who.group) && snapshot_represents(apps[who.group], snapshot, prefix)
                && committed_prefix_before(h, t, who.group, prefix),
        _ => true,
    })
}
